// Multiple choice — Domain 3.0 Security Architecture
PBQ.addMC(3, [
{ id:"d3-001", q:"In which cloud model is the customer responsible for patching the guest operating system?",
  o:["IaaS","PaaS","SaaS","FaaS"], a:0,
  e:"With IaaS you manage everything from the OS up. In PaaS, SaaS, and FaaS the provider manages the OS." },
{ id:"d3-002", q:"Regardless of cloud model, which responsibility ALWAYS stays with the customer?",
  o:["Data classification and access to the data","Physical security of the data center","Hypervisor patching","Network hardware maintenance"], a:0,
  e:"Customers always own their data, identities, and access decisions. Physical infrastructure is always the provider's." },
{ id:"d3-003", q:"A firewall is configured so that if it fails, all traffic is blocked. What failure mode is this?",
  o:["Fail-closed","Fail-open","Fail-safe for availability","Active-passive"], a:0,
  e:"Fail-closed favors security (confidentiality). Fail-open favors availability by letting traffic through when the device fails." },
{ id:"d3-004", q:"A badge-controlled door must unlock during a power failure so people can evacuate a fire. Which failure mode is required?",
  o:["Fail-open","Fail-closed","Fail-secure","Fail-over"], a:0,
  e:"Life safety comes first. Doors on exit paths fail open (fail-safe for people)." },
{ id:"d3-005", q:"What is the key difference between an IDS and an IPS?",
  o:["An IPS sits inline and can block traffic; an IDS monitors a copy of traffic and alerts","An IDS blocks traffic; an IPS only alerts","An IPS uses signatures only; an IDS uses anomaly detection only","There is no difference"], a:0,
  e:"An IPS is inline (active) and can drop packets. An IDS is passive, usually on a SPAN port or tap, and only alerts." },
{ id:"d3-006", q:"Which device inspects HTTP traffic at layer 7 to block SQL injection and XSS against a web application?",
  o:["WAF","Layer 4 firewall","Load balancer","VPN concentrator"], a:0,
  e:"A web application firewall understands HTTP and application-layer attacks. A layer 4 firewall only sees IPs and ports." },
{ id:"d3-007", q:"Which appliance combines firewall, IPS, antivirus, content filtering, and VPN in one device, often for small businesses?",
  o:["UTM","WAF","Jump server","SIEM"], a:0,
  e:"Unified threat management bundles many functions into one appliance. It's simpler to run, but it's a single point of failure." },
{ id:"d3-008", q:"Which next-generation firewall feature allows a rule like 'allow Microsoft Teams, block BitTorrent' no matter which port is used?",
  o:["Application awareness","Stateful inspection","NAT","Port forwarding"], a:0,
  e:"NGFWs identify applications by their traffic patterns (layer 7), not just by port numbers." },
{ id:"d3-009", q:"A forward proxy is MOST commonly used to:",
  o:["Filter and cache outbound user web traffic","Distribute inbound traffic across web servers","Terminate site-to-site VPNs","Assign IP addresses"], a:0,
  e:"Forward proxies sit between users and the internet for content filtering, logging, and caching. Reverse proxies sit in front of servers." },
{ id:"d3-010", q:"Which IPsec component provides encryption of the payload?",
  o:["ESP","AH","IKE","GRE"], a:0,
  e:"Encapsulating Security Payload provides confidentiality (and can provide integrity). AH provides integrity and authentication only, with no encryption. IKE negotiates keys." },
{ id:"d3-011", q:"Which IPsec mode encrypts the ENTIRE original IP packet and is typically used between two VPN gateways?",
  o:["Tunnel mode","Transport mode","Aggressive mode","Main mode"], a:0,
  e:"Tunnel mode wraps the whole packet in a new IP header, which suits site-to-site VPNs. Transport mode encrypts only the payload, host to host." },
{ id:"d3-012", q:"A company wants to connect branch offices over multiple internet links with centralized, application-aware routing. Which technology fits BEST?",
  o:["SD-WAN","MPLS only","SASE","802.1X"], a:0,
  e:"SD-WAN optimizes WAN connectivity. SASE adds cloud-delivered security services on top of it." },
{ id:"d3-013", q:"Which approach separates the network control plane from the data plane so the network can be managed centrally in software?",
  o:["Software-defined networking (SDN)","Air gapping","VLAN trunking","Spanning tree"], a:0,
  e:"SDN centralizes control in software controllers and makes the network programmable." },
{ id:"d3-014", q:"Which is the BIGGEST security concern with ICS/SCADA systems?",
  o:["Legacy protocols without authentication, and systems that can't be patched easily","Too many software updates","Excessive encryption overhead","Users installing mobile apps"], a:0,
  e:"ICS prioritizes availability and safety. Many systems run old, unauthenticated protocols (Modbus, DNP3) and can't be taken offline to patch." },
{ id:"d3-015", q:"Which TWO data protection methods replace sensitive data with a non-sensitive substitute? (Choose two.)",
  o:["Tokenization","Masking","Hashing with salt","Full disk encryption","Geographic restriction"], a:[0,1],
  e:"Tokenization swaps data for a token mapped in a vault. Masking hides part or all of the value (e.g., ***-**-1234). Encryption and hashing transform the data itself." },
{ id:"d3-016", q:"Customer data must legally stay in the EU and be subject to EU law. Which concept is this?",
  o:["Data sovereignty","Data masking","Data custodianship","Data minimization"], a:0,
  e:"Data sovereignty means data is subject to the laws of the country where it's stored. That drives geographic restrictions on storage." },
{ id:"d3-017", q:"Data being processed in a server's RAM is in which state?",
  o:["Data in use","Data at rest","Data in transit","Data in archive"], a:0,
  e:"In use = being processed (memory or CPU). At rest = stored. In transit = moving over a network." },
{ id:"d3-018", q:"Which classification is MOST appropriate for a company's unreleased product designs?",
  o:["Confidential / proprietary (trade secret)","Public","Unclassified","Regulated PHI"], a:0,
  e:"Intellectual property and trade secrets need restricted classification. PHI is health data regulated by HIPAA." },
{ id:"d3-019", q:"Which backup approach captures the state of a virtual machine at a point in time, often in seconds?",
  o:["Snapshot","Differential","Tape rotation","Journaling"], a:0,
  e:"Snapshots record VM or storage state almost instantly. They're great for rollback but aren't a replacement for offsite backups." },
{ id:"d3-020", q:"Which provides power for a few minutes to allow a graceful shutdown or a generator start?",
  o:["UPS","Generator","PDU","Dual power supplies"], a:0,
  e:"An uninterruptible power supply bridges short outages. Generators provide long-term power once they start." },
{ id:"d3-021", q:"Which type of DR test has team members walk through a scenario in a conference room without touching any systems?",
  o:["Tabletop exercise","Failover test","Parallel processing","Simulation"], a:0,
  e:"Tabletop exercises are discussion-based, low cost, and good for validating plans and roles." },
{ id:"d3-022", q:"Running production at both the primary and DR sites at the same time to confirm the DR site produces identical results is called:",
  o:["Parallel processing","Tabletop exercise","Cold site test","Snapshot test"], a:0,
  e:"In a parallel test, both systems run together and their outputs are compared, with no risk to production." },
{ id:"d3-023", q:"Using both AWS and Azure so that one provider's outage doesn't take down a critical service is an example of:",
  o:["Multi-cloud / platform diversity","Vendor lock-in","Geographic dispersion only","Serverless"], a:0,
  e:"Platform or vendor diversity removes a single provider as a point of failure." },
{ id:"d3-024", q:"Which load balancer configuration has all nodes serving traffic at the same time?",
  o:["Active-active","Active-passive","Cold standby","Round-robin DNS only"], a:0,
  e:"Active-active uses all nodes and gives more capacity. Active-passive keeps a standby that takes over on failure." },
{ id:"d3-025", q:"Which EAP method requires certificates on BOTH the client and the server?",
  o:["EAP-TLS","PEAP","EAP-TTLS","EAP-FAST"], a:0,
  e:"EAP-TLS uses mutual certificate authentication and is the strongest option. PEAP and TTLS need only a server certificate and tunnel the user's credentials inside it." },
{ id:"d3-026", q:"Which is the MAIN security benefit of infrastructure as code (IaC)?",
  o:["Consistent, repeatable, version-controlled configurations that reduce drift","It removes the need for patching","It encrypts all traffic automatically","It eliminates insider threats"], a:0,
  e:"IaC templates can be reviewed, scanned, and versioned, so every deployment matches the approved baseline." },
{ id:"d3-027", q:"Which architecture runs code only when triggered and bills per execution, with no server for the customer to manage?",
  o:["Serverless","Containers","Virtual machines","Microservices"], a:0,
  e:"Serverless (FaaS) hides the server completely. Security focuses on code, function permissions, and API triggers." },
{ id:"d3-028", q:"An organization stores backups in a different region at least 100 miles away from the primary data center. What does this provide?",
  o:["Geographic dispersion","Platform diversity","Load balancing","Clustering"], a:0,
  e:"Distance protects against regional disasters like floods, hurricanes, and power grid failures." },
{ id:"d3-029", q:"A switch port is configured to allow only the first MAC address it learns and shut down if another appears. What is this?",
  o:["Port security","802.1X","DHCP snooping","Spanning tree"], a:0,
  e:"Port security limits or pins MAC addresses per port. 802.1X instead requires authentication through RADIUS." },
{ id:"d3-030", q:"Which TWO are benefits of a jump server? (Choose two.)",
  o:["Single controlled path for administrative access","Centralized logging and monitoring of admin sessions","Load balancing web traffic","Replacing MFA","Encrypting data at rest"], a:[0,1],
  e:"Jump servers funnel admin access through one hardened, monitored host, which reduces exposure of management interfaces." }
]);
